package main

import (
	"bytes"
	"fmt"
	"go/format"
	"regexp"
	"slices"
	"strings"
)

const generatedHeader = "// Code generated by gostack-codegen. DO NOT EDIT.\n\n"

// printer collects the text of one generated file.
type printer struct {
	buf bytes.Buffer
}

// f writes one formatted line.
func (p *printer) f(layout string, args ...any) {
	fmt.Fprintf(&p.buf, layout, args...)
	p.buf.WriteByte('\n')
}

// blank writes an empty line.
func (p *printer) blank() {
	p.buf.WriteByte('\n')
}

// importPaths maps the package names generated code uses to their import
// paths. A file imports the ones whose name it mentions.
var importPaths = map[string]string{
	"awsjson":  "github.com/kylecannon/gostack/internal/protocol/awsjson",
	"awserr":   "github.com/kylecannon/gostack/internal/awserr",
	"context":  "context",
	"errors":   "errors",
	"http":     "net/http",
	"io":       "io",
	"maps":     "maps",
	"protocol": "github.com/kylecannon/gostack/internal/protocol",
	"query":    "github.com/kylecannon/gostack/internal/protocol/query",
	"request":  "github.com/kylecannon/gostack/internal/request",
	"service":  "github.com/kylecannon/gostack/internal/service",
	"slices":   "slices",
	"url":      "net/url",
}

// literals matches what is not code: line comments, interpreted strings and raw
// strings. An import is needed only when the code outside them uses its package.
var literals = regexp.MustCompile("(?m)//.*$|\"(?:\\\\.|[^\"\\\\])*\"|`[^`]*`")

// render turns the body of a file into formatted Go source with its header,
// package clause and imports.
func (g *generator) render(body string) ([]byte, error) {
	var names []string

	code := literals.ReplaceAllString(body, "")

	for name := range importPaths {
		if regexp.MustCompile(`\b` + name + `\.`).MatchString(code) {
			names = append(names, name)
		}
	}

	slices.Sort(names)

	var src strings.Builder

	src.WriteString(generatedHeader)
	fmt.Fprintf(&src, "package %s\n\n", g.name)

	if len(names) > 0 {
		src.WriteString("import (\n")

		// Standard library first, then the module's own packages.
		for _, local := range []bool{false, true} {
			for _, name := range names {
				if strings.Contains(importPaths[name], ".") == local {
					fmt.Fprintf(&src, "\t%q\n", importPaths[name])
				}
			}

			if !local {
				src.WriteString("\n")
			}
		}

		src.WriteString(")\n\n")
	}

	src.WriteString(body)

	out, err := format.Source([]byte(src.String()))
	if err != nil {
		return nil, fmt.Errorf("format generated code: %w\n%s", err, numbered(src.String()))
	}

	return out, nil
}

// numbered prefixes each line with its number, for error messages.
func numbered(src string) string {
	lines := strings.Split(src, "\n")
	for i, line := range lines {
		lines[i] = fmt.Sprintf("%5d  %s", i+1, line)
	}

	return strings.Join(lines, "\n")
}

// files returns the six generated files of the service by name.
func (g *generator) files() (map[string][]byte, error) {
	bodies := map[string]func() (string, error){
		"types.go":       g.typesFile,
		"operations.go":  g.operationsFile,
		"errors.go":      g.errorsFile,
		"codec_json.go":  g.jsonFile,
		"codec_query.go": g.queryFile,
		"dispatch.go":    g.dispatchFile,
	}

	out := make(map[string][]byte, len(bodies))

	for _, name := range sortedKeys(bodies) {
		body, err := bodies[name]()
		if err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}

		src, err := g.render(body)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}

		out[name] = src
	}

	return out, nil
}
